struct env_hdr { uint32_t magic; uint16_t version; uint16_t type; uint32_t len; };
/* wrap at the outbound adapter */
struct env_hdr h = { htonl(0x454E5631u), htons(1), htons(MSG_ORDER), htonl(payload_len) };
memcpy(out, &h, sizeof h);
memcpy(out + sizeof h, payload, payload_len);
/* unwrap at the destination: validate, then hand the tail to the application */
uint32_t n = ntohl(h.len);
if (n > received_len - sizeof h) return -EINVAL;
dispatch(ntohs(h.type), out + sizeof h, n);
